<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useAuthStore } from '@/stores/auth'
import { ApiError } from '@/services/api'
import { createCloudflareZone, createPrimaryDomain, grantPrimaryDomain, listCloudflareConnections, listCloudflareZones, listPrimaryDomains, listTeams, precheckDomainDns, revokePrimaryDomainGrant, updateCloudflareZone, updatePrimaryDomain } from '@/services/resources'
import type { CloudflareConnection, CloudflareZone, DnsPrecheckResult, PrimaryDomain, Team } from '@/types/api'
import IconBase from '@/components/IconBase.vue'
import ModalDialog from '@/components/ModalDialog.vue'
import PageState from '@/components/PageState.vue'
import StatusBadge from '@/components/StatusBadge.vue'

const auth=useAuthStore(),domains=ref<PrimaryDomain[]>([]),zones=ref<CloudflareZone[]>([]),connections=ref<CloudflareConnection[]>([]),teams=ref<Team[]>([])
const loading=ref(true),error=ref(''),notice=ref(''),mode=ref<'zone'|'domain'|'grant'|'precheck'|null>(null),busy=ref(false),formError=ref(''),selected=ref<PrimaryDomain|null>(null),precheckResult=ref<DnsPrecheckResult|null>(null)
const zoneForm=reactive({connection_id:'',external_zone_id:'',zone_name:''}),domainForm=reactive({zone_id:'',domain_name:''})
const hostname=ref('')
const activeGrantIds=computed(()=>new Set((selected.value?.grants||[]).filter(g=>g.status==='active').map(g=>g.team_id)))
const message=(e:unknown)=>e instanceof ApiError?e.message:'操作失败，请稍后重试。'
async function load(){loading.value=true;error.value='';try{domains.value=await listPrimaryDomains();if(auth.isSuperAdmin){[zones.value,connections.value,teams.value]=await Promise.all([listCloudflareZones(),listCloudflareConnections(),listTeams()])}}catch(e){error.value=message(e)}finally{loading.value=false}}
function show(kind:'zone'|'domain'){mode.value=kind;formError.value='';if(kind==='zone')Object.assign(zoneForm,{connection_id:connections.value[0]?.id||'',external_zone_id:'',zone_name:''});else Object.assign(domainForm,{zone_id:zones.value[0]?.id||'',domain_name:''})}
async function save(){busy.value=true;formError.value='';try{if(mode.value==='zone'){await createCloudflareZone(zoneForm);notice.value='Zone 已登记为未验证，未调用 Cloudflare。'}else if(mode.value==='domain'){await createPrimaryDomain(domainForm);notice.value='主域名已登记，是否可用取决于 Zone 与连接验证状态。'}mode.value=null;await load()}catch(e){formError.value=message(e)}finally{busy.value=false}}
function grants(item:PrimaryDomain){selected.value=item;formError.value='';mode.value='grant'}
async function setGrant(team:Team){if(!selected.value)return;busy.value=true;formError.value='';try{if(activeGrantIds.value.has(team.id))await revokePrimaryDomainGrant(selected.value.id,team.id);else await grantPrimaryDomain(selected.value.id,team.id);await load();selected.value=domains.value.find(d=>d.id===selected.value?.id)||null;notice.value='团队授权状态已更新。'}catch(e){formError.value=message(e)}finally{busy.value=false}}
async function disableDomain(item:PrimaryDomain){if(!confirm(`停用主域名 ${item.domain_name}？`))return;try{await updatePrimaryDomain(item.id,'disabled');notice.value='主域名已停用，未删除 DNS。';await load()}catch(e){error.value=message(e)}}
async function setZoneState(item:CloudflareZone,state:'enabled'|'disabled'){if(!confirm(`${state==='disabled'?'停用':'重新启用'} Zone ${item.zone_name}？`))return;try{await updateCloudflareZone(item.id,state,item.version);notice.value='Zone 管理员状态已更新，未修改 DNS。';await load()}catch(e){error.value=message(e)}}
function openPrecheck(item:PrimaryDomain){selected.value=item;hostname.value=item.domain_name;precheckResult.value=null;formError.value='';mode.value='precheck'}
async function runPrecheck(){if(!selected.value)return;busy.value=true;formError.value='';try{precheckResult.value=await precheckDomainDns(selected.value.id,hostname.value)}catch(e){formError.value=message(e)}finally{busy.value=false}}
onMounted(load)
</script>
<template>
  <div class="page-header"><div><span class="eyebrow">Domain registry</span><h1>域名管理</h1><p>{{auth.isSuperAdmin?'登记 Zone、主域名并管理团队授权。':'查看团队当前获授权的主域名资源。'}}</p></div><div v-if="auth.isSuperAdmin" class="header-actions"><button class="btn btn-secondary" @click="show('zone')">登记 Zone</button><button class="btn btn-primary" @click="show('domain')"><IconBase name="plus"/>登记主域名</button></div></div>
  <div v-if="notice" class="alert alert-success page-alert">{{notice}}</div>
  <PageState :loading="loading" :error="error" :empty="!domains.length" empty-title="暂无可见主域名" empty-text="只有后端授权范围内的资源会显示；员工只看到当前可用资源。" @retry="load">
    <div class="domain-grid"><article v-for="item in domains" :key="item.id" class="content-card domain-card"><header><div class="domain-mark"><IconBase name="domain"/></div><div><h2>{{item.domain_name}}</h2><code>{{item.id}}</code></div><StatusBadge :value="item.domain_status"/></header><dl><div><dt>Zone</dt><dd>{{item.zone_name}} <StatusBadge :value="item.zone_verification_status"/></dd></div><div><dt>连接</dt><dd>{{item.connection_label}} <StatusBadge :value="item.connection_verification_status"/></dd></div><div><dt>可用性</dt><dd><span :class="['availability',item.available&&'available']"><i/>{{item.available?'可用于新实例':'未验证或已停用'}}</span></dd></div><div><dt>团队授权</dt><dd>{{auth.isSuperAdmin?`${item.grants.filter(g=>g.status==='active').length} 个活动授权`:'本团队已授权'}}</dd></div></dl><footer v-if="auth.isSuperAdmin"><button class="btn-link" @click="openPrecheck(item)">DNS 只读检查</button><button class="btn-link" @click="grants(item)">管理授权</button><button v-if="item.domain_status==='active'" class="btn-link danger" @click="disableDomain(item)">停用</button></footer></article></div>
  </PageState>
  <section v-if="auth.isSuperAdmin&&zones.length" class="content-card zone-section"><div class="card-heading"><div><h2>已登记 Zone</h2><p>显示只读验证得到的实际状态。</p></div></div><div class="table-wrap"><table><thead><tr><th>Zone</th><th>连接</th><th>外部 ID</th><th>状态</th><th class="align-right">操作</th></tr></thead><tbody><tr v-for="zone in zones" :key="zone.id"><td><b>{{zone.zone_name}}</b></td><td>{{zone.connection_label}} <StatusBadge :value="zone.connection_verification_status"/></td><td><code>{{zone.external_zone_id}}</code></td><td><StatusBadge :value="zone.admin_state"/> <StatusBadge :value="zone.verification_status"/> <small>{{zone.cloudflare_status||'未读取'}}</small></td><td class="align-right"><button v-if="zone.admin_state==='enabled'" class="btn-link danger" @click="setZoneState(zone,'disabled')">停用</button><button v-else class="btn-link" @click="setZoneState(zone,'enabled')">重新启用</button></td></tr></tbody></table></div></section>
  <ModalDialog :open="mode==='zone'||mode==='domain'" :title="mode==='zone'?'登记 Zone':'登记主域名'" description="仅登记控制面资源，不会创建或修改 DNS。" @close="mode=null"><form class="modal-form" @submit.prevent="save"><div v-if="formError" class="alert">{{formError}}</div><template v-if="mode==='zone'"><label>Cloudflare 连接<select v-model="zoneForm.connection_id" required><option v-for="item in connections.filter(c=>c.admin_state==='enabled')" :key="item.id" :value="item.id">{{item.label}}（{{item.verification_status}}）</option></select></label><label>Cloudflare Zone ID<input v-model.trim="zoneForm.external_zone_id" required/></label><label>Zone 名称<input v-model.trim="zoneForm.zone_name" required placeholder="example.com"/></label></template><template v-else><label>所属 Zone<select v-model="domainForm.zone_id" required><option v-for="item in zones.filter(z=>z.admin_state==='enabled'&&z.connection_admin_state==='enabled')" :key="item.id" :value="item.id">{{item.zone_name}}（{{item.verification_status}}）</option></select></label><label>主域名<input v-model.trim="domainForm.domain_name" required placeholder="pages.example.com"/></label></template><footer><button type="button" class="btn btn-secondary" @click="mode=null">取消</button><button class="btn btn-primary" :disabled="busy">保存</button></footer></form></ModalDialog>
  <ModalDialog :open="mode==='grant'" title="团队域名授权" :description="selected?.domain_name" @close="mode=null"><div class="modal-form"><div v-if="formError" class="alert">{{formError}}</div><div class="grant-list"><div v-for="team in teams" :key="team.id"><div><b>{{team.name}}</b><small>{{activeGrantIds.has(team.id)?'当前可见':'未授权或已撤销'}}</small></div><button class="btn btn-small" :class="activeGrantIds.has(team.id)?'btn-secondary danger-outline':'btn-primary'" :disabled="busy" @click="setGrant(team)">{{activeGrantIds.has(team.id)?'撤销':'授权'}}</button></div></div></div></ModalDialog>
  <ModalDialog :open="mode==='precheck'" title="DNS 只读预检查" :description="selected?.domain_name" @close="mode=null"><form class="modal-form" @submit.prevent="runPrecheck"><div v-if="formError" class="alert">{{formError}}</div><label>候选完整域名<input v-model.trim="hostname" required/></label><div v-if="precheckResult" class="security-note"><b>{{precheckResult.classification}}</b>：{{precheckResult.message}}<small v-for="record in precheckResult.records" :key="record.id">{{record.type}} {{record.name}} → {{record.content}}</small></div><footer><button type="button" class="btn btn-secondary" @click="mode=null">关闭</button><button class="btn btn-primary" :disabled="busy">只读检查</button></footer></form></ModalDialog>
</template>
